/* Gel's chat: filled tonal containers, large soft corners, no hairlines. Every color is made from the
   theme's own (--agent-text, --agent-accent), which Gel's theme file sets to the seed's tones for light
   and dark (DESIGN.md), so the stylesheet follows the appearance and the person's theme edits.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. */
:root {
  --cv-text: var(--agent-text);
  --cv-text-muted: color-mix(in srgb, color-mix(in srgb, var(--agent-text) 90%, var(--agent-accent)) 85%, transparent);
  --cv-text-dim: color-mix(in srgb, color-mix(in srgb, var(--agent-text) 95%, var(--agent-accent)) 66%, transparent);
  --cv-link: var(--agent-accent);
  --agent-link: var(--agent-accent);
  --cv-card-fill: color-mix(in srgb, color-mix(in srgb, var(--agent-text) 65%, var(--agent-accent)) 6%, transparent);
  --cv-card-ring: transparent;
  --cv-user-bubble-tint: color-mix(in srgb, color-mix(in srgb, var(--agent-text) 5%, var(--agent-accent)) 21%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 14px;
}

files.customize/main.js:
// Gel's sidebar: a hover card built from tonal containers, and calm rows with the arc while work runs.
// Public surfaces only: cmux.hovercard/1 and cmux.sidebar.rows/1 (docs/cmux-next/sidebar-customization.md).
// Colors are the theme's semantic tokens (`selected`, `accent`, `secondary`), so the card follows light
// and dark live; no hex color is written here.

// The App's own glass under a node (paint only, no layout change). An older cmux has no `.glass`, so the
// node draws without it rather than throwing.
const glass = (node, level) => (typeof node.glass === "function" ? node.glass(level) : node)

// Two kinds of chip, both caption text with a soft 8 pt corner. A state chip floats on the App's chip
// glass (`.glass` replaces `.background` where the App has it, so an older cmux shows the tonal fill);
// a place chip is a filled tonal container in the theme's `selected` tone.
const pad = (node) =>
  node.font("caption").weight("medium").lineLimit(1).paddingHorizontal(8).paddingVertical(3).cornerRadius(8)
const stateChip = (text) => glass(pad(Text(text)).background("selected"), "chip")
const placeChip = (text) => pad(Text(text)).background("selected")

const fact = (card, kind) => card.facts.find((f) => f.kind === kind)

// The card: what it is and its state on one line, why it waits (the one thing that may need you),
// what it was asked, and where it is, as chips.
function renderCard(ctx) {
  const card = ctx.card
  const waiting = fact(card, "needsInput")
  const task = fact(card, "task")
  const reply = fact(card, "lastReply")
  const where = ["branch", "pullRequest"].map((kind) => fact(card, kind)).filter(Boolean)
  return VStack({ spacing: 8 }, [
    HStack({ spacing: 8 }, [
      Text(card.title).font("headline").lineLimit(2),
      Spacer(),
      card.status ? stateChip(card.status) : Text(card.age ?? "").font("caption").secondary(),
    ]),
    waiting ? Text(waiting.text).color("accent").weight("medium").lineLimit(3) : null,
    task ? Text(task.text).lineLimit(3) : null,
    reply ? Text(reply.text).secondary().lineLimit(2) : null,
    where.length ? HStack({ spacing: 4 }, where.map((f) => placeChip(f.text))) : null,
  ])
}

// Rows: medium names, and the circular arc as the loading indicator.
function decorateRows() {
  const workspaces = cmux.live("workspace.list", {})
  return VStack([
    ForEach({ items: () => workspaces() ?? [], key: (w) => w.id }, (w) =>
      Group({ title: () => w().name, weight: () => "medium", indicator: () => "arc" }, []),
    ),
  ])
}

globalThis.__cmuxAppExports = { renderCard, decorateRows }

files.themes/gel.json:
// Gel: soft tonal surfaces from one sea-glass seed (#2f8fa3), light and dark. Every color below is a
// tone of that seed's palettes (DESIGN.md): the page is the surface tone, the selection the primary
// container, the accent the primary. No hairlines: surfaces part by tone. The window, title area and
// sidebar are native glass at 88% of the surface tone; the chat stays opaque so text never shows
// through. The terminal theme is a light/dark pair, so each appearance gets its own tones.
{
  "name": "Gel",
  "description": "Sea-glass tonal surfaces, light and dark, with glass where layers float and no hairlines.",

  // One theme per appearance; each one's colors are appearance.themeEdits of that theme.
  "appearance.theme": "light:Builtin Light,dark:Builtin Dark",
  // cmux's own window, sidebar and pages follow the terminal theme, not the person's App Theme.
  "appearance.appTheme": "followTerminal",
  "appearance.themeEdits": {
    "Builtin Light/background": "#f5fafc",
    "Builtin Light/foreground": "#171c1e",
    "Builtin Light/cursor": "#006879",
    "Builtin Light/selection": "#a9edff",
    "Builtin Light/accent": "#006879",
    "Builtin Dark/background": "#0f1416",
    "Builtin Dark/foreground": "#dee3e5",
    "Builtin Dark/cursor": "#84d2e6",
    "Builtin Dark/selection": "#3e7d8b",
    "Builtin Dark/accent": "#84d2e6"
  },
  "appearance.accent": "theme",

  // Glass behind the chrome: no picture, the system material, the surface tone at 88% over it.
  "appearance.background": "none",
  "appearance.backgroundBlur": "glass",
  "appearance.backgroundOpacity": 0.88,

  // Flat chrome keeps the flush corner (the selected tab runs into the content card), with a subtle
  // tonal step around the card instead of a line. No borders anywhere.
  "appearance.chromeStyle": "flat",
  "appearance.titleAreaTone": "subtleTone",
  "appearance.borders": "none",

  // The sidebar floats on the window glass; the chat is an opaque surface-tone card.
  "appearance.sidebarSurface": "same",
  "appearance.surfaces.agentPane.opacity": 1,
  "sidebar.sectionLook": "card",

  // The circular arc while work runs; roomy density (compact would turn the flush corner off).
  "appearance.statusIndicator.style": "arc",
  "appearance.density": "comfortable"
}
